    private void cmbCategoriasActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_cmbCategoriasActionPerformed
       String categoria = cmbCategorias.getSelectedItem().toString();
       lblEjercicios.setText(categoria);
if (categoria.equals("Pierna")) {
    lblEjercicios.setText("Sentadilla");
}    
if (categoria.equals("Pecho")) {
    lblEjercicios.setText("Press de banca");
}   
if (categoria.equals("Espalda")) {
    lblEjercicios.setText("Jalón al pecho");
}    
if (categoria.equals("Hombros")) {
    lblEjercicios.setText("Elevaciones laterales");
}   
if (categoria.equals("Bíceps")) {
    lblEjercicios.setText("Curl de bíceps");
}   
if (categoria.equals("Tríceps")) {
    lblEjercicios.setText("Extensión de tríceps");
}


    }//GEN-LAST:event_cmbCategoriasActionPerformed

    private void btnVerInstruccionesActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnVerInstruccionesActionPerformed
    String categoria = cmbCategorias.getSelectedItem().toString(); 
    
    
    if (categoria.equals("Seleccione una categoría")) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Primero debe seleccionar una categoría");
    return;
}    
 if (categoria.equals("Pierna")) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Ejercicio: Sentadilla\n\n"
            + "Descripción: Ejercicio para fortalecer las piernas.\n\n"
            + "Instrucciones:\n"
            + "1. Coloque los pies al ancho de los hombros.\n"
            + "2. Flexione las rodillas y baje la cadera.\n"
            + "3. Mantenga la espalda recta.\n"
            + "4. Regrese lentamente a la posición inicial.");
}       

if (categoria.equals("Pecho")) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Ejercicio: Press de banca\n\n"
            + "Descripción: Ejercicio para fortalecer los músculos del pecho.\n\n"
            + "Instrucciones:\n"
            + "1. Acuéstese sobre el banco con los pies apoyados.\n"
            + "2. Sujete la barra con las manos separadas.\n"
            + "3. Baje la barra de forma controlada hacia el pecho.\n"
            + "4. Empuje la barra hasta extender los brazos.");
}
        
if (categoria.equals("Espalda")) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Ejercicio: Jalón al pecho\n\n"
            + "Descripción: Ejercicio para fortalecer los músculos de la espalda.\n\n"
            + "Instrucciones:\n"
            + "1. Siéntese frente a la máquina de polea alta.\n"
            + "2. Sujete la barra con ambas manos.\n"
            + "3. Lleve la barra hacia la parte superior del pecho.\n"
            + "4. Regrese lentamente a la posición inicial.");
}

if (categoria.equals("Hombros")) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Ejercicio: Elevaciones laterales\n\n"
            + "Descripción: Ejercicio para fortalecer los músculos de los hombros.\n\n"
            + "Instrucciones:\n"
            + "1. Colóquese de pie con una mancuerna en cada mano.\n"
            + "2. Mantenga los brazos ligeramente flexionados.\n"
            + "3. Eleve los brazos hacia los lados hasta la altura de los hombros.\n"
            + "4. Baje lentamente las mancuernas a la posición inicial.");
}

if (categoria.equals("Bíceps")) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Ejercicio: Curl de bíceps\n\n"
            + "Descripción: Ejercicio para fortalecer los músculos del bíceps.\n\n"
            + "Instrucciones:\n"
            + "1. Colóquese de pie con una mancuerna en cada mano.\n"
            + "2. Mantenga los codos cerca del cuerpo.\n"
            + "3. Flexione los brazos elevando las mancuernas.\n"
            + "4. Baje lentamente hasta la posición inicial.");
}

if (categoria.equals("Tríceps")) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Ejercicio: Extensión de tríceps\n\n"
            + "Descripción: Ejercicio para fortalecer los músculos del tríceps.\n\n"
            + "Instrucciones:\n"
            + "1. Colóquese frente a una máquina de polea alta.\n"
            + "2. Sujete la barra con ambas manos.\n"
            + "3. Extienda los brazos hacia abajo manteniendo los codos cerca del cuerpo.\n"
            + "4. Regrese lentamente a la posición inicial.");
}


        
        
    }//GEN-LAST:event_btnVerInstruccionesActionPerformed

